'use strict';

// MODULES //

var base = require( './base.js' );


// MAIN //

/**
* Returns the value of the one-norm, Frobenius norm, infinity-norm, or the largest absolute value of any element of a real symmetric matrix `A` using alternative indexing semantics.
*
* @param {string} norm - specifies the norm type
* @param {string} uplo - specifies whether the upper or lower triangular part of `A` is referenced ('upper' or 'lower')
* @param {NonNegativeInteger} N - order of the matrix `A`
* @param {Float64Array} A - input matrix
* @param {integer} strideA1 - stride of the first dimension of `A`
* @param {integer} strideA2 - stride of the second dimension of `A`
* @param {NonNegativeInteger} offsetA - starting index for `A`
* @returns {number} matrix norm
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 1.0, 2.0, 2.0, 5.0 ] );
*
* var norm = dlansy( 'M', 'upper', 2, A, 2, 1, 0 );
* // returns 5.0
*/
function dlansy( norm, uplo, N, A, strideA1, strideA2, offsetA ) {
	return base( norm, uplo, N, A, strideA1, strideA2, offsetA );
}


// EXPORTS //

module.exports = dlansy;
